def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes with O(n log log n) time and O(n) memory.
    """
    if n <= 2:
        return 0
    limit = n
    # bytearray for memory efficiency; 1 means prime candidate
    is_prime = bytearray(b'\x01') * limit
    # 0 and 1 are not prime
    if limit > 0:
        is_prime[0] = 0
    if limit > 1:
        is_prime[1] = 0
    import math
    max_p = int(math.isqrt(limit - 1))
    for p in range(2, max_p + 1):
        if is_prime[p]:
            start = p * p
            step = p
            # slice assignment to mark multiples as non‑prime
            is_prime[start:limit:step] = b'\x00' * ((limit - 1 - start) // step + 1)
    return sum(is_prime)

