def solve(mat):
    # Determinant of square matrix, empty matrix => 1
    if not mat:
        return 1
    n = len(mat)
    # Verify square maybe assume correct.
    from fractions import Fraction
    # make a copy as Fractions
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det *= -1
        pivot_val = a[i][i]
        det *= pivot_val
        # normalize row i
        for j in range(i, n):
            a[i][j] /= pivot_val
        # eliminate below
        for k in range(i+1, n):
            factor = a[k][i]
            if factor != 0:
                for j in range(i, n):
                    a[k][j] -= factor * a[i][j]
    # det is product of pivots (already multiplied)
    # It should be integer
    return int(det)

