def solve(matrix) -> int:
    """Determinant of a square integer matrix, returned as an int.

    Uses the Bareiss (fraction-free) algorithm so every intermediate
    value stays an exact integer. An empty matrix has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    a = [list(row) for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if a[k][k] == 0:
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    sign = -sign
                    break
            else:
                return 0
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * a[k][k] - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = a[k][k]
    return sign * a[n - 1][n - 1]

def solve(mat):
    """Return the determinant of a square integer matrix.
    Empty matrix returns 1 as specified.
    Uses Gaussian elimination with exact rational arithmetic (Fraction) to avoid overflow.
    """
    if not mat:
        return 1
    n = len(mat)
    from fractions import Fraction
    # copy matrix as Fractions for exact arithmetic
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for i in range(n):
        # find a non-zero pivot in column i
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det *= -1
        pivot_val = a[i][i]
        det *= pivot_val
        # scale row i to make pivot 1 (optional, keeps numbers smaller)
        for j in range(i, n):
            a[i][j] /= pivot_val
        # eliminate entries below pivot
        for k in range(i + 1, n):
            factor = a[k][i]
            if factor != 0:
                for j in range(i, n):
                    a[k][j] -= factor * a[i][j]
    # determinant is product of pivots (det already holds it)
    # Convert to int (det is integer for integer matrices)
    return int(det)

