def solve(grid):
    """Count islands in a possibly irregular grid.
    An island is a group of cells with value 1 connected 4‑directionally.
    The grid may have rows of different lengths or be empty.
    """
    if not grid:
        return 0
    visited = set()
    def is_land(i, j):
        return (
            0 <= i < len(grid) and
            0 <= j < len(grid[i]) and
            grid[i][j] == 1
        )
    def dfs(start_i, start_j):
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # explore four neighbours if they are land
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if is_land(ni, nj) and (ni, nj) not in visited:
                    stack.append((ni, nj))
    count = 0
    for i, row in enumerate(grid):
        for j in range(len(row)):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

