def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    supply of given *coins* (list of positive ints). Return -1 if impossible.
    Uses DP with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # DP array where dp[i] is min coins for amount i, init large
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
