def solve(coins, amount):
    """Return the minimum number of coins needed to make *amount* using unlimited
    supply of given *coins* (list of positive ints). Return -1 if impossible.
    Classic DP solution O(amount * len(coins))."""
    if amount < 0:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with binary search for O(n log n) time.
    """
    import bisect
    tails = []  # tails[i] is the smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find insertion point (first >= x) because strictly increasing
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

