def solve(matrix):
    """Return the determinant of an integer square matrix.
    Empty matrix (i.e., []) returns 1 as per specification.
    Uses the Bareiss algorithm for exact integer arithmetic.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a copy to avoid mutating the input
    A = [list(row) for row in matrix]
    det_sign = 1
    prev_pivot = 1
    for k in range(n - 1):
        # Ensure pivot is non-zero; if zero, swap with a lower row
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
        prev_pivot = pivot
    return det_sign * A[n - 1][n - 1]

