def solve(n, edges):
    """Return the lexicographically smallest topological ordering of a directed graph.
    n: number of nodes (0 <= n)
    edges: list of [a, b] pairs where 0 <= a,b < n.
    If a cycle exists, return an empty list.
    """
    if n <= 0:
        return []
    from heapq import heappush, heappop
    # Deduplicate edges and ignore invalid ones
    seen = set()
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if not (0 <= a < n and 0 <= b < n):
            continue
        if (a, b) in seen:
            continue
        seen.add((a, b))
        adj[a].append(b)
        indeg[b] += 1
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    if len(order) != n:
        return []
    return order

def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Tokens are strings representing integers or operators.
    """
    stack = []
    for tok in tokens:
        if tok in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division
                # Truncate toward zero
                res = int(a / b)
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

